{
  "headline": "FDA's records trace our supply to a plant classified OAI 623 days before the posting",
  "headline_cites": ["D7"],
  "sentences": [
    {
      "text": "FDA lists diltiazem hydrochloride injection from Hospira, Inc. as To Be Discontinued with an initial posting date of 2018-02-21.",
      "cites": ["E24"]
    },
    {
      "text": "The product labels at both Corvale General and Corvale East identify Hospira, Inc. as the labeler for NDC 00409435003.",
      "cites": ["E4", "E1"]
    },
    {
      "text": "FDA inspection 976095 at Hospira, Inc. (FEI 1925262) ended 2016-06-08 and was classified OAI, 623 days before the shortage posting.",
      "cites": ["D7", "E11"]
    },
    {
      "text": "A Warning Letter was issued to the same plant on 2017-02-14, 372 days before the posting.",
      "cites": ["D8", "E16"]
    },
    {
      "text": "A later FDA inspection 1064827 at the plant ended 2018-08-15 and was classified OAI, 175 days after the posting.",
      "cites": ["D11", "E13"]
    },
    {
      "text": "As of 2026-10-21 the discontinuation has been on FDA's list for 104 months.",
      "cites": ["D14"]
    },
    {
      "text": "The rule-based best option is to transfer 50 vials of 100 mg from Corvale General to Corvale East, which would raise Corvale East from 9.3 days to 14 days on hand while Corvale General retains two weeks of supply.",
      "cites": ["D15", "D1", "D2"]
    }
  ]
}
